 UX_PROJECT11(id);const p=openingById6(id);if(!p)return;const content=el('modalContent'),group=(start,end,label)=>{if(!start)return;const details=document.createElement('details');details.className='ux-project-details11';details.innerHTML='<summary>'+label+'</summary>';start.before(details);let n=start;while(n&&n!==end){const next=n.nextSibling;details.append(n);n=next;}};
 const heads=[...content.querySelectorAll('h3')],policy=heads.find(h=>h.textContent==='Pravomoci přípravy'),history=heads.find(h=>h.textContent==='Co se opravdu stalo'),costs=[...content.children].find(n=>n.classList.contains('rows'));if(costs)group(costs,policy||history,'Náklady a harmonogram');if(policy)group(policy,history,'Pravomoci a další nábor');if(history)group(history,null,'Historie zaplacených kroků');
