 UX_OPEN11(...args);if(!el('openConfirm')||el('uxOpenNext11'))return;
 const content=el('modalContent'),fields=el('openBrand').closest('.fields'),preview=el('openingPreview5'),confirm=el('openConfirm'),steps=document.createElement('div'),form=document.createElement('div'),review=document.createElement('div'),footer=document.createElement('div');steps.className='ux-open-steps11';steps.innerHTML='<span class="active">1 · Tvůj podnik</span><span>2 · Rozpočet a zahájení</span>';fields.before(steps);steps.after(form);form.append(fields);const advanced=document.createElement('details');advanced.className='ux-open-advanced11';advanced.innerHTML='<summary>Smlouva, směny a vedoucí</summary><div class="fields"></div>';form.append(advanced);for(const id of ['openTenure5','openingShift6','openingManager6'])advanced.querySelector('div').append(el(id).closest('.field'));
 form.after(review);review.append(preview);review.hidden=true;footer.className='ux-open-footer11';footer.innerHTML='<button class="soft" id="uxOpenBack11" hidden>← Upravit podnik</button><button class="primary" id="uxOpenNext11">Zkontrolovat rozpočet →</button>';footer.append(confirm);confirm.hidden=true;content.append(footer);
 const change=showReview=>{form.hidden=showReview;review.hidden=!showReview;confirm.hidden=!showReview;el('uxOpenNext11').hidden=showReview;el('uxOpenBack11').hidden=!showReview;steps.children[0].classList.toggle('active',!showReview);steps.children[1].classList.toggle('active',showReview);el('modalContent').scrollTop=0;(showReview?el('uxOpenBack11'):el('openDesign5')).focus({preventScroll:true});};el('uxOpenNext11').onclick=()=>change(true);el('uxOpenBack11').onclick=()=>change(false);el('openBrand').focus({preventScroll:true});
