let uxConfirm11=null;
function uxRestoreConfirm11(){const saved=uxConfirm11;if(!saved)return;uxConfirm11=null;el('modalContent').replaceChildren(...saved.nodes);el('modal').setAttribute('aria-labelledby',saved.title);el('modalContent').scrollTop=saved.scroll;saved.focus?.focus({preventScroll:true});}
confirmAction=function(...args){const content=el('modalContent'),parent=el('modal').open&&content.querySelector('input,select,textarea')&&!el('confirmAction')?{nodes:[...content.childNodes],focus:document.activeElement,title:el('modal').getAttribute('aria-labelledby'),scroll:el('modalContent').scrollTop}:null;UX_BASE10.confirmAction(...args);uxConfirm11=parent;if(parent){el('cancelAction').textContent='Zpět k úpravám';el('cancelAction').onclick=uxRestoreConfirm11;const commit=el('confirmAction').onclick;el('confirmAction').onclick=()=>{uxConfirm11=null;commit();};}};
el('close').addEventListener('click',e=>{if(uxConfirm11){e.preventDefault();e.stopImmediatePropagation();uxRestoreConfirm11();}},true);
