el('modal').addEventListener('click',e=>{if(uxConfirm11&&e.target===el('modal')){const r=el('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){e.stopImmediatePropagation();uxRestoreConfirm11();}}},true);
