help=function(){UX_BASE10.help();const p=document.createElement('p');p.textContent='Stálá lišta nabízí Mapu, Kavárny, Kávu, Jídlo, Lidi a Firmu. Více otevře všechny podrobné oblasti. Zpět se vrací k předchozí obrazovce, Mapa do rozpracovaného světa. V dlouhých stránkách přepínej podstránky nahoře. Hledání najde i řidiče, akademii nebo 250g produkty bez diakritiky (Ctrl/Cmd + K). Týdenní výsledek se objeví v malé kartě; celý report otevřeš jejím tlačítkem. Reporty a společný servis jsou v horní nabídce Reporty a údržba. Přepnutí podstránky zachová rozepsaná pole na stejné stránce; platí až tlačítko Uložit nebo zaplacené potvrzení.';el('modalContent').append(p);};el('help').onclick=help;
const skip=document.createElement('a');skip.className='ux-skip10';skip.href='#content';skip.textContent='Přejít na správu firmy';document.body.prepend(skip);el('content').tabIndex=-1;if(digestActive6!==null&&el('modal').open){digestActive6=null;el('modal').close();}render();

function worldPasteSaveDialog12(){show(`<h2>Vložit uloženou hru</h2><p class="sub">Vlož celý obsah svého JSON souboru. Nejdřív prověříme platnost; hra se načte až po potvrzení.</p>${field('Obsah uložené hry',`<textarea id="worldSaveText12" rows="8" placeholder="Vlož obsah souboru…" spellcheck="false"></textarea>`)}<button class="primary" id="worldLoadText12">Prověřit a načíst</button>`);el('worldLoadText12').onclick=()=>{try{const text=el('worldSaveText12').value;if(new Blob([text]).size>3000000)throw Error('Uložená hra je příliš velká.');const candidate=validateSave(JSON.parse(text));confirmAction('Načíst uloženou hru?','Současný postup v tomto prohlížeči se nahradí. Firma '+esc(candidate.company||'Kavárna')+', týden '+candidate.week+', hotovost '+money(candidate.cash)+'.',()=>{state=candidate;view='city';city='Praha';selected=null;filterCity='all';notice='Hra načtena.';persist();render();},'Načíst hru');}catch(e){toast(e.message);}};}
